"use client";

import { useState } from "react";
import { FileCode2, Copy, Check, Download, Upload, Sparkles, AlertCircle } from "lucide-react";
import { formatFileSize } from "@/lib/audio-file-utils";

const SAMPLE_SVG = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" width="100" height="100">
  <!-- Generated by Vector Editor 2026 -->
  <!-- Author: Graphic Designer -->
  <metadata>
    <rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">
      <cc:Work rdf:about="" />
    </rdf:RDF>
  </metadata>
  <defs>
    <linearGradient id="grad1" x1="0%" y1="0%" x2="100%" y2="100%">
      <stop offset="0%" style="stop-color:#3b82f6;stop-opacity:1" />
      <stop offset="100%" style="stop-color:#8b5cf6;stop-opacity:1" />
    </linearGradient>
  </defs>
  <circle cx="50.00000" cy="50.00000" r="40.00000" fill="url(#grad1)" stroke="#1e1b4b" stroke-width="4.00000" />
  <path d="M 35.00000 50.00000 L 45.00000 60.00000 L 65.00000 40.00000" stroke="#ffffff" stroke-width="6.00000" stroke-linecap="round" stroke-linejoin="round" fill="none" />
</svg>`;

export default function SvgOptimizerTool() {
  const [svgInput, setSvgInput] = useState<string>(SAMPLE_SVG);
  const [precision, setPrecision] = useState<number>(2);
  const [removeComments, setRemoveComments] = useState<boolean>(true);
  const [removeMetadata, setRemoveMetadata] = useState<boolean>(true);
  const [collapseWhitespace, setCollapseWhitespace] = useState<boolean>(true);
  const [copied, setCopied] = useState<boolean>(false);

  // Optimization logic
  let optimized = svgInput;

  if (removeComments) {
    optimized = optimized.replace(/<!--[\s\S]*?-->/g, "");
  }

  if (removeMetadata) {
    optimized = optimized.replace(/<metadata[\s\S]*?<\/metadata>/gi, "");
    optimized = optimized.replace(/<\?xml[\s\S]*?\?>/gi, "");
    optimized = optimized.replace(/<!DOCTYPE[\s\S]*?>/gi, "");
    // Remove namespaced tags e.g. <sodipodi:namedview ... />
    optimized = optimized.replace(/<(sodipodi|inkscape):[\s\S]*?\/>/gi, "");
  }

  // Round floating point numbers
  if (precision >= 0) {
    optimized = optimized.replace(/\b(\d+\.\d{3,})\b/g, (match) => {
      return parseFloat(match).toFixed(precision);
    });
  }

  if (collapseWhitespace) {
    // Remove whitespace between tags
    optimized = optimized.replace(/>\s+</g, "><");
    // Collapse multiple internal spaces
    optimized = optimized.replace(/\s{2,}/g, " ");
    optimized = optimized.trim();
  }

  const origSize = new Blob([svgInput]).size;
  const optSize = new Blob([optimized]).size;
  const savingsPct = origSize > 0 ? Math.max(0, Math.round((1 - optSize / origSize) * 100)) : 0;

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      if (typeof event.target?.result === "string") {
        setSvgInput(event.target.result);
      }
    };
    reader.readAsText(file);
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(optimized);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleDownload = () => {
    const blob = new Blob([optimized], { type: "image/svg+xml;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "optimized.svg";
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-6">
      {/* Settings Bar */}
      <div className="bg-white border border-slate-200 rounded-3xl p-5 shadow-xs flex flex-wrap items-center justify-between gap-4">
        <div className="flex flex-wrap items-center gap-4 text-xs font-semibold text-slate-700">
          <label className="flex items-center gap-2 cursor-pointer select-none">
            <input
              type="checkbox"
              checked={removeComments}
              onChange={(e) => setRemoveComments(e.target.checked)}
              className="rounded accent-emerald-600"
            />
            <span>Strip Comments</span>
          </label>

          <label className="flex items-center gap-2 cursor-pointer select-none">
            <input
              type="checkbox"
              checked={removeMetadata}
              onChange={(e) => setRemoveMetadata(e.target.checked)}
              className="rounded accent-emerald-600"
            />
            <span>Strip Editor Metadata</span>
          </label>

          <label className="flex items-center gap-2 cursor-pointer select-none">
            <input
              type="checkbox"
              checked={collapseWhitespace}
              onChange={(e) => setCollapseWhitespace(e.target.checked)}
              className="rounded accent-emerald-600"
            />
            <span>Minify Whitespace</span>
          </label>

          <div className="flex items-center gap-1.5">
            <span>Precision:</span>
            <select
              value={precision}
              onChange={(e) => setPrecision(Number(e.target.value))}
              className="bg-slate-50 border border-slate-200 rounded-lg px-2 py-1 font-bold focus:outline-emerald-500"
            >
              <option value={1}>1 Decimal</option>
              <option value={2}>2 Decimals</option>
              <option value={3}>3 Decimals</option>
              <option value={-1}>Keep Original</option>
            </select>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <label className="cursor-pointer text-xs font-bold text-slate-700 hover:text-emerald-700 px-3 py-1.5 rounded-xl border border-slate-200 hover:border-emerald-200 transition-colors flex items-center gap-1.5">
            <Upload className="w-3.5 h-3.5" />
            Upload SVG
            <input type="file" accept=".svg,image/svg+xml" className="hidden" onChange={handleFileUpload} />
          </label>

          <button
            onClick={() => setSvgInput(SAMPLE_SVG)}
            className="text-xs font-semibold text-slate-400 hover:text-slate-600 px-2 py-1.5 transition-colors"
          >
            Reset Sample
          </button>
        </div>
      </div>

      {/* Savings Metric Banner */}
      <div className="bg-gradient-to-r from-emerald-500 to-teal-600 text-white rounded-3xl p-6 shadow-xs flex flex-wrap items-center justify-between gap-4">
        <div>
          <span className="text-xs uppercase tracking-wider font-bold text-emerald-100">Optimization Result</span>
          <h3 className="text-2xl sm:text-3xl font-black font-mono mt-0.5">
            {formatFileSize(optSize)} <span className="text-sm font-semibold opacity-80">(was {formatFileSize(origSize)})</span>
          </h3>
        </div>

        <div className="flex items-center gap-3">
          <div className="bg-white/20 backdrop-blur-md px-3.5 py-2 rounded-xl text-center">
            <span className="text-xs block text-emerald-100">Saved</span>
            <span className="text-xl font-black font-mono">-{savingsPct}%</span>
          </div>
          <button
            onClick={handleDownload}
            className="px-5 py-2.5 bg-white text-emerald-800 hover:bg-slate-100 font-bold text-xs rounded-xl flex items-center gap-1.5 transition-colors shadow-xs"
          >
            <Download className="w-4 h-4" />
            Download SVG
          </button>
        </div>
      </div>

      {/* Code Editor & Visual Preview */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Code Input & Output */}
        <div className="bg-white border border-slate-200 rounded-3xl p-5 shadow-xs space-y-3">
          <div className="flex items-center justify-between">
            <h4 className="text-xs font-bold text-slate-800 uppercase tracking-wider">Optimized SVG Code</h4>
            <button
              onClick={handleCopy}
              className="text-xs font-bold px-3 py-1.5 rounded-xl border border-slate-200 hover:border-emerald-300 hover:bg-emerald-50 text-slate-700 transition-colors flex items-center gap-1"
            >
              {copied ? <Check className="w-3.5 h-3.5 text-emerald-600" /> : <Copy className="w-3.5 h-3.5" />}
              {copied ? "Copied" : "Copy Code"}
            </button>
          </div>
          <textarea
            value={optimized}
            onChange={(e) => setSvgInput(e.target.value)}
            rows={12}
            className="w-full font-mono text-xs text-slate-800 bg-slate-50/60 p-3.5 rounded-2xl border border-slate-200 focus:outline-emerald-500 resize-y"
          />
        </div>

        {/* Live SVG Rendering Preview */}
        <div className="bg-white border border-slate-200 rounded-3xl p-5 shadow-xs flex flex-col justify-between">
          <h4 className="text-xs font-bold text-slate-800 uppercase tracking-wider mb-3">Live Visual Render</h4>
          <div className="flex-1 flex items-center justify-center p-6 bg-[repeating-conic-gradient(#f1f5f9_0%_25%,#ffffff_0%_50%)] bg-[length:16px_16px] rounded-2xl border border-slate-100 min-h-[220px]">
            <div
              className="max-h-[260px] max-w-full flex justify-center [&>svg]:max-h-[240px] [&>svg]:w-auto"
              dangerouslySetInnerHTML={{ __html: optimized }}
            />
          </div>
        </div>
      </div>
    </div>
  );
}
